<div class="event-admin-heading"><div><a class="event-back" href="<?= site_url('pengelola/kegiatan') ?>">← Semua kegiatan</a><h1><?= html_escape($event['title']) ?></h1><p>Daftar pendaftar dan status kehadiran.</p></div><div class="event-admin-actions"><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/studio') ?>">Studio</a><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/ubah') ?>">Ubah kegiatan</a></div></div><section class="event-admin-card"><div class="event-section-head"><h2>Peserta</h2><span><?= (int)$total ?> pendaftar</span></div><form class="staff-list-filter" method="get" action="<?= site_url('pengelola/kegiatan/'.$event['id'].'/peserta') ?>"><label>Cari peserta<input type="search" name="q" value="<?= html_escape($search) ?>" maxlength="80" placeholder="Nama atau kode pendaftaran"></label><label>Status<select name="status"><option value="">Semua</option><?php foreach(array('submitted'=>'Menunggu','confirmed'=>'Dikonfirmasi','rejected'=>'Ditolak','attended'=>'Hadir') as $value=>$label): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/peserta') ?>">Reset</a></form><?php if(!$participants): ?><div class="event-empty">Belum ada pendaftar.</div><?php endif; ?><div class="event-participant-list"><?php foreach($participants as $p): ?><article class="event-participant"><div><strong><?= html_escape($p['full_name']) ?></strong><small><?= html_escape($p['reference_no']) ?> · <?= html_escape(date('d M Y H:i',strtotime($p['submitted_at']))) ?></small><small><?= html_escape(substr($p['phone_e164'],0,5).'***'.substr($p['phone_e164'],-3)) ?></small></div><div class="event-participant-actions"><span class="event-badge <?= in_array($p['status'],array('confirmed','attended'),TRUE)?'live':'' ?>"><?= html_escape(array('submitted'=>'Menunggu','confirmed'=>'Dikonfirmasi','rejected'=>'Ditolak','attended'=>'Hadir')[$p['status']]??$p['status']) ?></span><?php $actions=array('submitted'=>array('confirmed'=>'Konfirmasi','rejected'=>'Tolak'),'confirmed'=>array('attended'=>'Tandai hadir','rejected'=>'Tolak'),'rejected'=>array('submitted'=>'Kembalikan'),'attended'=>array());foreach($actions[$p['status']]??array() as $next_status=>$label): ?><form method="post" action="<?= site_url('pengelola/kegiatan/pendaftaran/'.$p['id'].'/status') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="status" value="<?= $next_status ?>"><input type="hidden" name="page" value="<?= (int)$page ?>"><input type="hidden" name="q" value="<?= html_escape($search) ?>"><input type="hidden" name="filter_status" value="<?= html_escape($status) ?>"><input type="hidden" name="per_page" value="<?= (int)$per_page ?>"><button type="submit"><?= $label ?></button></form><?php endforeach; ?></div><?php if(!empty($answers[$p['id']])): ?><details class="event-participant-answers"><summary>Jawaban formulir</summary><?php foreach($answers[$p['id']] as $answer): ?><p><strong><?= html_escape($answer['label']) ?></strong><span><?= nl2br(html_escape($answer['answer_text'])) ?></span></p><?php endforeach; ?></details><?php endif; ?></article><?php endforeach; ?></div><?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/kegiatan/'.$event['id'].'/peserta'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
